//! Demiurge's one look (ADR-108), in QOR ID's tool register: the values its pages and emails use, and the faces its
//! pages load.
//!
//! `look/tokens.rs` and `look/fonts/` are generated by `node docs/design/tokens.mjs` from `docs/design/tokens.json`:
//! edit that, never them. `--check`, in CI, fails if they drift.
//!
//! - GET /fonts/{file}: one of the faces, embedded in the binary, so a page asks nothing of any other address.

use axum::{
    extract::Path,
    http::{HeaderValue, StatusCode, header},
    response::{IntoResponse, Response},
};

// Generated, and formatted as the generator writes it. It is the whole of the one look's values, as every surface's
// generated file is, so a page or a message can take any of them; those not taken yet are not dead code to remove.
#[rustfmt::skip]
#[allow(dead_code)]
pub mod tokens;

/// One face, by its file name. Unknown names are 404, and nothing else is read: the names are the embedded table's.
pub async fn font(Path(file): Path<String>) -> Response {
    let Some((_, bytes)) = tokens::FACES.iter().find(|(name, _)| *name == file) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let mut response = (StatusCode::OK, *bytes).into_response();
    let headers = response.headers_mut();
    headers.insert(header::CONTENT_TYPE, HeaderValue::from_static("font/woff2"));
    // A face never changes under its name: a new one is a new file.
    headers.insert(
        header::CACHE_CONTROL,
        HeaderValue::from_static("public, max-age=31536000, immutable"),
    );
    headers.insert(
        header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    response
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::body::to_bytes;

    #[tokio::test]
    async fn every_face_is_served_as_woff2_and_kept_a_year() {
        assert!(tokens::FACES.len() >= 8, "{} faces", tokens::FACES.len());
        for (name, bytes) in tokens::FACES {
            let response = font(Path((*name).to_string())).await;
            assert_eq!(response.status(), StatusCode::OK, "{name}");
            assert_eq!(response.headers()[header::CONTENT_TYPE], "font/woff2");
            assert_eq!(
                response.headers()[header::CACHE_CONTROL],
                "public, max-age=31536000, immutable"
            );
            let body = to_bytes(response.into_body(), usize::MAX).await.unwrap();
            assert_eq!(&body[..], *bytes, "{name}");
            assert_eq!(&body[..4], b"wOF2", "{name} is not a WOFF2 file");
        }
    }

    #[tokio::test]
    async fn an_unknown_face_is_not_found_and_nothing_else_is_read() {
        for name in [
            "",
            "nope.woff2",
            "../Cargo.toml",
            "fonts/barlow-latin-400-normal.woff2",
        ] {
            let response = font(Path(name.to_string())).await;
            assert_eq!(response.status(), StatusCode::NOT_FOUND, "{name}");
        }
    }

    #[test]
    fn every_face_the_stylesheet_names_is_served() {
        for (name, _) in tokens::FACES {
            assert!(tokens::CSS.contains(&format!("/fonts/{name}")), "{name}");
        }
        let named = tokens::CSS.matches("src: url(/fonts/").count();
        assert_eq!(named, tokens::FACES.len());
    }
}
